//! The glanceable label for an incident kind.

use bsc_incident::Kind;

/// The glanceable label for a kind — what a human reads before the body.
pub fn label_for(kind: Kind) -> &'static str {
    match kind {
        Kind::DeauthFlood => "Deauth flood",
        Kind::Jamming => "RF jamming",
        Kind::ScanDetected => "Network scan",
        Kind::RogueDhcp => "Rogue DHCP server",
        Kind::LeaseTheft => "Lease theft",
        Kind::NewDevice => "New device",
        // AUDIO. The label is what a person reads on a lock screen at 3am, so it says what was
        // HEARD, never what it might mean: "Loud impact", not "Fall detected". The ear measured a
        // sound; inferring a body from it is a claim the sensor cannot support, and a false
        // "Fall detected" is exactly the alarm that gets the system switched off.
        Kind::Impact => "Loud impact",
        Kind::Distress => "Raised voice",
        Kind::UnknownVoice => "Unfamiliar voice",
        Kind::Other => "Network alert",
    }
}
